import{_ as e,o as t,c as l,a2 as o}from"./chunks/framework.CqpfiAoK.js";const _=JSON.parse('{"title":"篇929｜万族共和文明宪章·第二十八条——轮回收割禁止","description":"","frontmatter":{"title":"篇929｜万族共和文明宪章·第二十八条——轮回收割禁止","no":929,"module":5,"tags":["宪章","第二十八条","轮回","收割禁止","灵魂权"],"related":["0004-反掠夺主义核心论纲","0082-时间回溯基本原则","0090-术语词典"]},"headers":[],"relativePath":"zh/0929_模块5-第二十八条-轮回收割禁止.md","filePath":"zh/0929_模块5-第二十八条-轮回收割禁止.md"}'),r={name:"zh/0929_模块5-第二十八条-轮回收割禁止.md"};function i(h,a,n,u,p,d){return t(),l("div",null,[...a[0]||(a[0]=[o('<h1 id="篇929-万族共和文明宪章·第二十八条——轮回收割禁止" tabindex="-1">篇929｜万族共和文明宪章·第二十八条——轮回收割禁止 <a class="header-anchor" href="#篇929-万族共和文明宪章·第二十八条——轮回收割禁止" aria-label="Permalink to &quot;篇929｜万族共和文明宪章·第二十八条——轮回收割禁止&quot;">​</a></h1><blockquote><p>所属模块：模块五·文明终极定型典藏篇｜对标地基：文档04、82、90</p></blockquote><h2 id="引言-轮回-不是任何人的庄稼地" tabindex="-1">引言：轮回，不是任何人的庄稼地 <a class="header-anchor" href="#引言-轮回-不是任何人的庄稼地" aria-label="Permalink to &quot;引言：轮回，不是任何人的庄稼地&quot;">​</a></h2><p>掠夺体系最隐蔽也最深的恶，是把轮回变成收割场：强者操纵轮回，让众生一世世修炼、一世世成长，然后在某个节点把一世世积累的本源、灵魂、气运一次性收割走。众生以为自己在轮回中修行，实则是在替别人种地。第二十八条宣布轮回收割为非法——轮回是众生灵魂自然流转的权利，不是任何强者的私人农场。</p><p>本条款自始至终置于六大顶层公理之下——反掠夺主义公理划底线、万族共和公理立主体、集体升维公理定方向、因果自律公理守边界、法则优先公理保自洽，五者共同构成本条不可逾越的精神边界。</p><p>与前五公理并列，本条同样受公理六·众生全员无限均等法则约束：众生全员无限均等公理——锚点共生文明内所有生灵自带基础无限之力，佛系与懒狗保有保底基础无限而不被时代淘汰，卷王与少年至尊可叠加更多更高层级的无限，掠夺因此从根本上失去意义。</p><h2 id="一、法理依据" tabindex="-1">一、法理依据 <a class="header-anchor" href="#一、法理依据" aria-label="Permalink to &quot;一、法理依据&quot;">​</a></h2><p>本条依据《反掠夺主义核心论纲》（地基04）中&quot;气运掠夺&quot;&quot;精神奴役&quot;两形态，与《时间回溯基本原则》（地基82）。其法理是因果自律公理的终极使命之一：根除轮回收割。轮回收割之所以是最深的掠夺，在于它跨越生死、操纵因果，把无数个轮回的众生当成了一次性原料。衡元宙承认轮回的客观存在，但坚决否认任何人对轮回享有收割权。</p><h2 id="二、规范内容-禁止收割的具体边界" tabindex="-1">二、规范内容：禁止收割的具体边界 <a class="header-anchor" href="#二、规范内容-禁止收割的具体边界" aria-label="Permalink to &quot;二、规范内容：禁止收割的具体边界&quot;">​</a></h2><p>第二十八条划清轮回领域的红线：</p><ol><li>禁止收割：任何人不得操纵轮回机制，截取众生轮回中积累的本源、灵魂、气运为己用</li><li>禁止轮回农场：不得设计&quot;养一世、收一世&quot;的修炼骗局，诱导众生在不知情中被种植</li><li>禁止记忆篡改：不得为收割目的篡改众生轮回记忆，使其沦为不自知的养料</li><li>保护自然流转：轮回作为灵魂自然机制，其运行不受任何强者私利操纵</li><li>知识例外：仅允许研究轮回规律本身（知识），严禁借此开发收割技术</li></ol><h2 id="三、适用范围" tabindex="-1">三、适用范围 <a class="header-anchor" href="#三、适用范围" aria-label="Permalink to &quot;三、适用范围&quot;">​</a></h2><p>本条适用于一切触及轮回、灵魂、生死机制的个体与机构，尤其警惕掌握时间法则、灵魂法则的至高强者。越是能操纵轮回的存在，越受本条严格约束——因为他们最有能力、也最有动机搞收割。本条同样约束打着&quot;度化&quot;&quot;救世&quot;旗号行收割之实的伪善者。</p><h2 id="四、违反后果" tabindex="-1">四、违反后果 <a class="header-anchor" href="#四、违反后果" aria-label="Permalink to &quot;四、违反后果&quot;">​</a></h2><p>操纵轮回收割、设计轮回农场、篡改轮回记忆、以灵魂为原料修炼，均构成本条最严重的违宪之一。后果为：相关轮回机制强制重置，被收割的灵魂与本源尽力归还；施害者按反掠夺罪顶级条款处置——因其跨越生死、伤害无数轮回的众生，危害远超普通掠夺。本条不设&quot;为了大局&quot;的例外。</p><h2 id="五、监督机制" tabindex="-1">五、监督机制 <a class="header-anchor" href="#五、监督机制" aria-label="Permalink to &quot;五、监督机制&quot;">​</a></h2><p>本条由阿赖耶网络+多层监督中的轮回监测子系统执行：轮回流量、灵魂流向、异常截取点全程监测；任何对轮回机制的调用都受严格报备（参见跨位面操作报备制）；锚点监督委员会与时间法则委员会联合稽查轮回异常，一旦发现收割痕迹即全网溯源。</p><h2 id="六、一条永远不许碰的河" tabindex="-1">六、一条永远不许碰的河 <a class="header-anchor" href="#六、一条永远不许碰的河" aria-label="Permalink to &quot;六、一条永远不许碰的河&quot;">​</a></h2><p>第二十八条守护的，是一条谁也不许碰的河。轮回之河静静流淌，无数灵魂在其中生生灭灭、自然流转。在旧宇宙，曾有强者在河中布网，把一世世修炼成长的灵魂当作秋收的庄稼，按时收割。衡元宙把这条河划为绝对禁区：任何对轮回流量的异常截取，都会被网络溯源；任何打着度化救世旗号的收割伪善，都被彻底揭穿。这条河属于河里的每一个灵魂，不属于任何站在岸上的强者。守住这条河，就是守住每个生命每一世的尊严。</p><h2 id="五大核心落点" tabindex="-1">五大核心落点 <a class="header-anchor" href="#五大核心落点" aria-label="Permalink to &quot;五大核心落点&quot;">​</a></h2><ul><li><p>反能级浪费：轮回收割把无数世的努力一次性抽干，是宇宙尺度最骇人的能级浪费，本条根除之</p></li><li><p>反掠夺：本条是反掠夺公理在生死轮回维度的最后封锁</p></li><li><p>唐罗上限对比：唐罗式体系中轮回、转世常被强者当作棋子与养料；衡元宙轮回是众生权利，禁止任何人收割</p></li><li><p>万族全覆盖：被保护的是一切轮回中的灵魂，不分种族、不分生死</p></li><li><p>超多元全开放：轮回规律可研究、可知识共享，但收割技术永不开放</p></li><li><p>众生全员无限均等：每个生灵自带基础无限之力，佛系懒狗保有保底基础无限而不被淘汰，卷王与少年至尊可叠加更高层级的无限，掠夺因此从根本上失去意义</p></li></ul><h2 id="结论" tabindex="-1">结论 <a class="header-anchor" href="#结论" aria-label="Permalink to &quot;结论&quot;">​</a></h2><p>轮回收割禁止，是锚点共生文明守护众生灵魂的最后一道铁闸。它告诉宇宙间一切存在：轮回可以被研究，知识可以被分享，但众生的灵魂，谁也别想当作庄稼来收。这条守住了，文明才算真正对每一个生命的每一世负责。</p><h2 id="关联" tabindex="-1">关联 <a class="header-anchor" href="#关联" aria-label="Permalink to &quot;关联&quot;">​</a></h2><ul><li>关联文档：<a href="./0004-反掠夺主义核心论纲.html">0004-反掠夺主义核心论纲</a> · <a href="./0082-时间回溯基本原则.html">0082-时间回溯基本原则</a> · <a href="./0090-术语词典.html">0090-术语词典</a> · <a href="./0928_模块5-第二十七条-历史倒车防范.html">928-第二十七条历史倒车防范</a></li><li>官网：<a href="https://faker210.github.io/hengyuan-cosmos/zh/" target="_blank" rel="noreferrer">https://faker210.github.io/hengyuan-cosmos/zh/</a></li></ul>',25)])])}const c=e(r,[["render",i]]);export{_ as __pageData,c as default};
